   416  UA_StatusCode
   417  UA_Node_setAttributes(UA_Node *node, const void *attributes,
   418                        const UA_DataType *attributeType) {
   419
   420      /* Copy the attributes into the node */
   421      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   422      switch(node->nodeClass) {
   423      case UA_NODECLASS_OBJECT:
   424          CHECK_ATTRIBUTES(OBJECTATTRIBUTES);
   425          retval = copyObjectNodeAttributes((UA_ObjectNode*)node,
   426                                            (const UA_ObjectAttributes*)attributes);
   427          break;
   428      case UA_NODECLASS_VARIABLE:
   429          CHECK_ATTRIBUTES(VARIABLEATTRIBUTES);
   430          retval = copyVariableNodeAttributes((UA_VariableNode*)node,
   431                                              (const UA_VariableAttributes*)attributes);
   432          break;
   433      case UA_NODECLASS_OBJECTTYPE:
   434          CHECK_ATTRIBUTES(OBJECTTYPEATTRIBUTES);
   435          retval = copyObjectTypeNodeAttributes((UA_ObjectTypeNode*)node,
   436                                                (const UA_ObjectTypeAttributes*)attributes);
   437          break;
   438      case UA_NODECLASS_VARIABLETYPE:
   439          CHECK_ATTRIBUTES(VARIABLETYPEATTRIBUTES);
   440          retval = copyVariableTypeNodeAttributes((UA_VariableTypeNode*)node,
   441                                                  (const UA_VariableTypeAttributes*)attributes);
   442          break;
   443      case UA_NODECLASS_REFERENCETYPE:
   444          CHECK_ATTRIBUTES(REFERENCETYPEATTRIBUTES);
   445          retval = copyReferenceTypeNodeAttributes((UA_ReferenceTypeNode*)node,
   446                                                   (const UA_ReferenceTypeAttributes*)attributes);
   447          break;
   448      case UA_NODECLASS_DATATYPE:
   449          CHECK_ATTRIBUTES(DATATYPEATTRIBUTES);
   450          retval = copyDataTypeNodeAttributes((UA_DataTypeNode*)node,
   451                                              (const UA_DataTypeAttributes*)attributes);
   452          break;
   453      case UA_NODECLASS_VIEW:
   454          CHECK_ATTRIBUTES(VIEWATTRIBUTES);
   455          retval = copyViewNodeAttributes((UA_ViewNode*)node,
   456                                          (const UA_ViewAttributes*)attributes);
   457          break;
   458      case UA_NODECLASS_METHOD:
   459          CHECK_ATTRIBUTES(METHODATTRIBUTES);
   460          retval = copyMethodNodeAttributes((UA_MethodNode*)node,
   461                                            (const UA_MethodAttributes*)attributes);
   462          break;
   463      case UA_NODECLASS_UNSPECIFIED:
   464      default:
   465          retval = UA_STATUSCODE_BADNODECLASSINVALID;
   466      }
   467
   468      if(retval == UA_STATUSCODE_GOOD)
   469          retval = copyStandardAttributes(node, (const UA_NodeAttributes*)attributes);
   470      if(retval != UA_STATUSCODE_GOOD)
   471          UA_Node_deleteMembers(node);
   472      return retval;
   473  }
