   479  static UA_StatusCode
   480  addReferenceTarget(UA_NodeReferenceKind *refs, const UA_ExpandedNodeId *target) {
   481      UA_ExpandedNodeId *targets =
   482          (UA_ExpandedNodeId*) UA_realloc(refs->targetIds,
   483                                          sizeof(UA_ExpandedNodeId) * (refs->targetIdsSize+1));
   484      if(!targets)
   485          return UA_STATUSCODE_BADOUTOFMEMORY;
   486
   487      refs->targetIds = targets;
   488      UA_StatusCode retval =
   489          UA_ExpandedNodeId_copy(target, &refs->targetIds[refs->targetIdsSize]);
   490
   491      if(retval == UA_STATUSCODE_GOOD) {
   492          refs->targetIdsSize++;
   493      } else if(refs->targetIdsSize == 0) {
   494          /* We had zero references before (realloc was a malloc) */
   495          UA_free(refs->targetIds);
   496          refs->targetIds = NULL;
   497      }
   498      return retval;
   499  }
