   501  static UA_StatusCode
   502  addReferenceKind(UA_Node *node, const UA_AddReferencesItem *item) {
   503      UA_NodeReferenceKind *refs =
   504          (UA_NodeReferenceKind*)UA_realloc(node->references,
   505                                            sizeof(UA_NodeReferenceKind) * (node->referencesSize+1));
   506      if(!refs)
   507          return UA_STATUSCODE_BADOUTOFMEMORY;
   508      node->references = refs;
   509      UA_NodeReferenceKind *newRef = &refs[node->referencesSize];
   510      memset(newRef, 0, sizeof(UA_NodeReferenceKind));
   511
   512      newRef->isInverse = !item->isForward;
   513      UA_StatusCode retval = UA_NodeId_copy(&item->referenceTypeId, &newRef->referenceTypeId);
   514      retval |= addReferenceTarget(newRef, &item->targetNodeId);
   515
   516      if(retval == UA_STATUSCODE_GOOD) {
   517          node->referencesSize++;
   518      } else {
   519          UA_NodeId_deleteMembers(&newRef->referenceTypeId);
   520          if(node->referencesSize == 0) {
   521              UA_free(node->references);
   522              node->references = NULL;
   523          }
   524      }
   525      return retval;
   526  }
