   528  UA_StatusCode
   529  UA_Node_addReference(UA_Node *node, const UA_AddReferencesItem *item) {
   530      UA_NodeReferenceKind *existingRefs = NULL;
   531      for(size_t i = 0; i < node->referencesSize; ++i) {
   532          UA_NodeReferenceKind *refs = &node->references[i];
   533          if(refs->isInverse != item->isForward
   534                  && UA_NodeId_equal(&refs->referenceTypeId, &item->referenceTypeId)) {
   535              existingRefs = refs;
   536              break;
   537          }
   538      }
   539      if(existingRefs != NULL) {
   540          for(size_t i = 0; i < existingRefs->targetIdsSize; i++) {
   541              if(UA_ExpandedNodeId_equal(&existingRefs->targetIds[i],
   542                                         &item->targetNodeId)) {
   543                  return UA_STATUSCODE_BADDUPLICATEREFERENCENOTALLOWED;
   544              }
   545          }
   546          return addReferenceTarget(existingRefs, &item->targetNodeId);
   547      }
   548      return addReferenceKind(node, item);
   549  }
