   551  UA_StatusCode
   552  UA_Node_deleteReference(UA_Node *node, const UA_DeleteReferencesItem *item) {
   553      for(size_t i = node->referencesSize; i > 0; --i) {
   554          UA_NodeReferenceKind *refs = &node->references[i-1];
   555          if(item->isForward == refs->isInverse)
   556              continue;
   557          if(!UA_NodeId_equal(&item->referenceTypeId, &refs->referenceTypeId))
   558              continue;
   559
   560          for(size_t j = refs->targetIdsSize; j > 0; --j) {
   561              if(!UA_NodeId_equal(&item->targetNodeId.nodeId, &refs->targetIds[j-1].nodeId))
   562                  continue;
   563
   564              /* Ok, delete the reference */
   565              UA_ExpandedNodeId_deleteMembers(&refs->targetIds[j-1]);
   566              refs->targetIdsSize--;
   567
   568              /* One matching target remaining */
   569              if(refs->targetIdsSize > 0) {
   570                  if(j-1 != refs->targetIdsSize) // avoid valgrind error: Source
   571                                                 // and destination overlap in
   572                                                 // memcpy
   573                      refs->targetIds[j-1] = refs->targetIds[refs->targetIdsSize];
   574                  return UA_STATUSCODE_GOOD;
   575              }
   576
   577              /* Remove refs */
   578              UA_free(refs->targetIds);
   579              UA_NodeId_deleteMembers(&refs->referenceTypeId);
   580              node->referencesSize--;
   581              if(node->referencesSize > 0) {
   582                  if(i-1 != node->referencesSize) // avoid valgrind error: Source
   583                                                  // and destination overlap in
   584                                                  // memcpy
   585                      node->references[i-1] = node->references[node->referencesSize];
   586                  return UA_STATUSCODE_GOOD;
   587              }
   588
   589              /* Remove the node references */
   590              UA_free(node->references);
   591              node->references = NULL;
   592              return UA_STATUSCODE_GOOD;
   593          }
   594      }
   595      return UA_STATUSCODE_UNCERTAINREFERENCENOTDELETED;
   596  }
