   598  void UA_Node_deleteReferences(UA_Node *node) {
   599      for(size_t i = 0; i < node->referencesSize; ++i) {
   600          UA_NodeReferenceKind *refs = &node->references[i];
   601          UA_Array_delete(refs->targetIds, refs->targetIdsSize, &UA_TYPES[UA_TYPES_EXPANDEDNODEID]);
   602          UA_NodeId_deleteMembers(&refs->referenceTypeId);
   603      }
   604      if(node->references)
   605          UA_free(node->references);
   606      node->references = NULL;
   607      node->referencesSize = 0;
