   279  static UA_StatusCode
   280  UA_NodeMap_getNodeCopy(void *context, const UA_NodeId *nodeid,
   281                         UA_Node **outNode) {
   282      UA_NodeMap *ns = (UA_NodeMap*)context;
   283      BEGIN_CRITSECT(ns);
   284      UA_NodeMapEntry **slot = findOccupiedSlot(ns, nodeid);
   285      if(!slot) {
   286          END_CRITSECT(ns);
   287          return UA_STATUSCODE_BADNODEIDUNKNOWN;
   288      }
   289      UA_NodeMapEntry *entry = *slot;
   290      UA_NodeMapEntry *newItem = newEntry(entry->node.nodeClass);
   291      if(!newItem) {
   292          END_CRITSECT(ns);
   293          return UA_STATUSCODE_BADOUTOFMEMORY;
   294      }
   295      UA_StatusCode retval = UA_Node_copy(&entry->node, &newItem->node);
   296      if(retval == UA_STATUSCODE_GOOD) {
   297          newItem->orig = entry; // store the pointer to the original
   298          *outNode = &newItem->node;
   299      } else {
   300          deleteEntry(newItem);
   301      }
   302      END_CRITSECT(ns);
   303      return retval;
   304  }
