   872  /* Prepare the node, then add it to the nodestore */
   873  UA_StatusCode
   874  Operation_addNode_begin(UA_Server *server, UA_Session *session, void *nodeContext,
   875                          const UA_AddNodesItem *item, const UA_NodeId *parentNodeId,
   876                          const UA_NodeId *referenceTypeId, UA_NodeId *outNewNodeId) {
   877      /* Do not check access for server */
   878      if(session != &adminSession && server->config.accessControl.allowAddNode &&
   879         !server->config.accessControl.allowAddNode(&session->sessionId, session->sessionHandle, item)) {
   880          return UA_STATUSCODE_BADUSERACCESSDENIED;
   881      }
   882
   883      /* Check the namespaceindex */
   884      if(item->requestedNewNodeId.nodeId.namespaceIndex >= server->namespacesSize) {
   885          UA_LOG_INFO_SESSION(server->config.logger, session,
   886                              "AddNodes: Namespace invalid");
   887          return UA_STATUSCODE_BADNODEIDINVALID;
   888      }
   889
   890      if(item->nodeAttributes.encoding != UA_EXTENSIONOBJECT_DECODED &&
   891         item->nodeAttributes.encoding != UA_EXTENSIONOBJECT_DECODED_NODELETE) {
   892          UA_LOG_INFO_SESSION(server->config.logger, session,
   893                              "AddNodes: Node attributes invalid");
   894          return UA_STATUSCODE_BADINTERNALERROR;
   895      }
   896
   897      /* Create a node */
   898      UA_Node *node = UA_Nodestore_new(server, item->nodeClass);
   899      if(!node) {
   900          UA_LOG_INFO_SESSION(server->config.logger, session,
   901                              "AddNodes: Node could not create a node "
   902                              "in the nodestore");
   903          return UA_STATUSCODE_BADOUTOFMEMORY;
   904      }
   905
   906      /* Fill the node */
   907      node->context = nodeContext;
   908      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   909      retval |= UA_NodeId_copy(&item->requestedNewNodeId.nodeId, &node->nodeId);
   910      retval |= UA_QualifiedName_copy(&item->browseName, &node->browseName);
   911      retval |= UA_Node_setAttributes(node, item->nodeAttributes.content.decoded.data,
   912                                                  item->nodeAttributes.content.decoded.type);
   913      if(retval != UA_STATUSCODE_GOOD) {
   914          UA_LOG_INFO_SESSION(server->config.logger, session,
   915                              "AddNodes: Node could not create a node "
   916                              "with error code %s",
   917                              UA_StatusCode_name(retval));
   918          UA_Nodestore_delete(server, node);
   919          return retval;
   920      }
   921
   922      if(server->bootstrapNS0)
   923          goto finished_checks;
   924
   925      /* Use attributes from the typedefinition */
   926      if(node->nodeClass == UA_NODECLASS_VARIABLE ||
   927         node->nodeClass == UA_NODECLASS_VARIABLETYPE) {
   928          /* Use attributes from the type. The value and value constraints are the
   929           * same for the variable and variabletype attribute structs. */
   930          retval = useVariableTypeAttributes(server, session,
   931                                             (UA_VariableNode*)node, item);
   932          if(retval != UA_STATUSCODE_GOOD) {
   933              UA_LOG_INFO_SESSION(server->config.logger, session,
   934                                  "AddNodes: Using attributes from the variable type "
   935                                  "failed with error code %s",
   936                                  UA_StatusCode_name(retval));
   937              UA_Nodestore_delete(server, node);
   938              return retval;
   939          }
   940      }
   941
   942   finished_checks:
   943
   944      /* Add the node to the nodestore */
   945      retval = UA_Nodestore_insert(server, node, outNewNodeId);
   946      if(retval != UA_STATUSCODE_GOOD) {
   947          UA_LOG_INFO_SESSION(server->config.logger, session,
   948                              "AddNodes: Node could not add the new node "
   949                                  "to the nodestore with error code %s",
   950                              UA_StatusCode_name(retval));
   951          return retval;
   952      }
   953
   954      retval = addParentAndTypeRef(server, session, node, parentNodeId, referenceTypeId, &item->typeDefinition.nodeId);
   955      if(retval != UA_STATUSCODE_GOOD) {
   956          UA_LOG_INFO_SESSION(server->config.logger, session,
   957                              "AddNodes: Node could add parent references with error code %s",
   958                              UA_StatusCode_name(retval));
   959          UA_Nodestore_delete(server, node);
   960      }
   961
   962      return retval;
   963  }
