   411  static status
   412  Array_encodeBinaryOverlayable(uintptr_t ptr, size_t length, size_t elementMemSize, Ctx *ctx) {
   413      /* Store the number of already encoded elements */
   414      size_t finished = 0;
   415
   416      /* Loop as long as more elements remain than fit into the chunk */
   417      while(ctx->end < ctx->pos + (elementMemSize * (length-finished))) {
   418          size_t possible = ((uintptr_t)ctx->end - (uintptr_t)ctx->pos) / (sizeof(u8) * elementMemSize);
   419          size_t possibleMem = possible * elementMemSize;
   420          memcpy(ctx->pos, (void*)ptr, possibleMem);
   421          ctx->pos += possibleMem;
   422          ptr += possibleMem;
   423          finished += possible;
   424          status ret = exchangeBuffer(ctx);
   425          if(ret != UA_STATUSCODE_GOOD)
   426              return ret;
   427      }
   428
   429      /* Encode the remaining elements */
   430      memcpy(ctx->pos, (void*)ptr, elementMemSize * (length-finished));
   431      ctx->pos += elementMemSize * (length-finished);
   432      return UA_STATUSCODE_GOOD;
   433  }
