   463  static status
   464  Array_encodeBinary(const void *src, size_t length, const UA_DataType *type, Ctx *ctx) {
   465      /* Check and convert the array length to int32 */
   466      i32 signed_length = -1;
   467      if(length > UA_INT32_MAX)
   468          return UA_STATUSCODE_BADINTERNALERROR;
   469      if(length > 0)
   470          signed_length = (i32)length;
   471      else if(src == UA_EMPTY_ARRAY_SENTINEL)
   472          signed_length = 0;
   473
   474      /* Encode the array length */
   475      status ret = ENCODE_WITHEXCHANGE(&signed_length, UInt32);
   476
   477      /* Quit early? */
   478      if(ret != UA_STATUSCODE_GOOD || length == 0)
   479          return ret;
   480
   481      /* Encode the content */
   482      if(!type->overlayable)
   483          return Array_encodeBinaryComplex((uintptr_t)src, length, type, ctx);
   484      return Array_encodeBinaryOverlayable((uintptr_t)src, length, type->memSize, ctx);
   485  }
