   487  static status
   488  Array_decodeBinary(void *UA_RESTRICT *UA_RESTRICT dst, size_t *out_length,
   489                     const UA_DataType *type, Ctx *ctx) {
   490      /* Decode the length */
   491      i32 signed_length;
   492      status ret = DECODE_DIRECT(&signed_length, UInt32); /* Int32 */
   493      if(ret != UA_STATUSCODE_GOOD)
   494          return ret;
   495
   496      /* Return early for empty arrays */
   497      if(signed_length <= 0) {
   498          *out_length = 0;
   499          if(signed_length < 0)
   500              *dst = NULL;
   900          return DECODE_DIRECT(&dst->content.encoded.body, String); /* ByteString */
   901      }
   902
   903      /* Allocate memory */
   904      dst->content.decoded.data = UA_new(type);
   905      if(!dst->content.decoded.data)
   906          return UA_STATUSCODE_BADOUTOFMEMORY;
   907
   908      /* Jump over the length field (TODO: check if the decoded length matches) */
   909      ctx->pos += 4;
   910
   911      /* Decode */
   912      dst->encoding = UA_EXTENSIONOBJECT_DECODED;
   913      dst->content.decoded.type = type;
   914      size_t decode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   915      return decodeBinaryJumpTable[decode_index](dst->content.decoded.data, type, ctx);
   916  }
