   918  DECODE_BINARY(ExtensionObject) {
   919      u8 encoding = 0;
   920      UA_NodeId binTypeId; /* Can contain a string nodeid. But no corresponding
   921                            * type is then found in open62541. We only store
   922                            * numerical nodeids of the binary encoding identifier.
   923                            * The extenionobject will be decoded to contain a
   924                            * binary blob. */
   925      UA_NodeId_init(&binTypeId);
   926      status ret = UA_STATUSCODE_GOOD;
   927      ret |= DECODE_DIRECT(&binTypeId, NodeId);
   928      ret |= DECODE_DIRECT(&encoding, Byte);
   929      if(ret != UA_STATUSCODE_GOOD) {
   930          UA_NodeId_deleteMembers(&binTypeId);
   931          return ret;
   932      }
   933
   934      if(encoding == UA_EXTENSIONOBJECT_ENCODED_BYTESTRING) {
   935          ret = ExtensionObject_decodeBinaryContent(dst, &binTypeId, ctx);
   936          UA_NodeId_deleteMembers(&binTypeId);
   937      } else if(encoding == UA_EXTENSIONOBJECT_ENCODED_NOBODY) {
   938          dst->encoding = (UA_ExtensionObjectEncoding)encoding;
   939          dst->content.encoded.typeId = binTypeId; /* move to dst */
   940          dst->content.encoded.body = UA_BYTESTRING_NULL;
   941      } else if(encoding == UA_EXTENSIONOBJECT_ENCODED_XML) {
   942          dst->encoding = (UA_ExtensionObjectEncoding)encoding;
   943          dst->content.encoded.typeId = binTypeId; /* move to dst */
   944          ret = DECODE_DIRECT(&dst->content.encoded.body, String); /* ByteString */
   945          if(ret != UA_STATUSCODE_GOOD)
   946              UA_NodeId_deleteMembers(&dst->content.encoded.typeId);
   947      } else {
   948          UA_NodeId_deleteMembers(&binTypeId);
   949          ret = UA_STATUSCODE_BADDECODINGERROR;
   950      }
   951
   952      return ret;
   953  }
